import { Component, OnInit, Input } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { NbDialogRef } from '@nebular/theme';

export interface InputOptions {
	value: string;
	label: string;
}

export interface PromptDialogOptions {
	inputType?: 'text' | 'email' | 'number' | 'checkbox' | 'radio' | 'password' | 'textarea' | 'select';
	title?: string;
	label?: string;
	okText?: string;
	cancelText?: string;
	placeholder?: string;
	options?: InputOptions[];
	/** Initial value of the input, e.g. the current name when renaming something. */
	value?: string;
}

@Component({
    selector: 'ngx-prompt',
    templateUrl: './prompt.component.html',
    styleUrls: ['./prompt.component.scss'],
    standalone: false
})
export class PromptComponent implements OnInit {
	@Input() data: PromptDialogOptions;

	form: UntypedFormGroup;
	showPassword = false;

	constructor(private readonly dialogRef: NbDialogRef<PromptComponent>, private readonly fb: UntypedFormBuilder) {
		this.form = this.fb.group({
			input: ['', Validators.required]
		});
	}

	/**
	 * Seeds the input with the caller's initial value, so an "edit" style prompt
	 * (rename, ...) does not force the user to retype what is already there.
	 */
	ngOnInit() {
		if (this.data?.value) {
			this.form.patchValue({ input: this.data.value });
		}
	}

	close() {
		this.dialogRef.close();
	}

	submit() {
		if (this.form.valid) {
			this.dialogRef.close(this.form.get('input').value);
		}
	}

	getInputType() {
		if (this.showPassword) {
			return 'text';
		}
		return 'password';
	}

	toggleShowPassword() {
		this.showPassword = !this.showPassword;
	}

	isInvalidControl(control: string) {
		if (!this.form.contains(control)) {
			return true;
		}
		return this.form.get(control).touched && this.form.get(control).invalid;
	}
}
